// Build the Outlook draft payload: letter as the HTML body, statement PDF as the attachment.
const json = $input.item.json;
const binary = $input.item.binary ?? {};

const accountNumber = (json.accountNumber || '').toString().trim();
const accountName = (json.accountName || '').toString().trim();
const statementDate = new Date().toISOString().slice(0, 10);

// The statement workflow may name its binary property anything; take the first PDF it hands us.
const statementKey =
  ['statement', 'data', 'pdf', 'file'].find((k) => binary[k]) ?? Object.keys(binary)[0];

if (!statementKey) {
  throw new Error(
    `No statement PDF found on the item for account ${accountNumber || '(unknown)'}. ` +
      'Check that the Printing Statements workflow returns the PDF as binary data.'
  );
}

const safeAccount = (accountNumber || 'account').replace(/[^A-Za-z0-9._-]/g, '_');
const attachmentName = `Statement_${safeAccount}_${statementDate}.pdf`;

// Wrap the letter so it renders as a standalone HTML email body.
const letterHtml = (json.letterHtml || '').toString().trim();
if (!letterHtml) {
  throw new Error(
    `No letter content found for account ${accountNumber || '(unknown)'}. ` +
      'Check the letterHtml mapping in "Normalize Account Fields".'
  );
}

const emailBodyHtml = letterHtml.toLowerCase().includes('<html')
  ? letterHtml
  : `<!doctype html><html><body style="font-family:Arial,Helvetica,sans-serif;font-size:11pt;color:#000;">${letterHtml}</body></html>`;

const emailSubject = accountName
  ? `Engelman's Bakery — Account Statement for ${accountName}`
  : `Engelman's Bakery — Account Statement${accountNumber ? ` (${accountNumber})` : ''}`;

return {
  json: {
    ...json,
    accountNumber,
    accountName,
    statementDate,
    emailSubject,
    emailBodyHtml,
    attachmentName,
  },
  binary: {
    ...binary,
    // Normalized name + filename so the Outlook node always finds the attachment.
    statement: { ...binary[statementKey], fileName: attachmentName, mimeType: 'application/pdf' },
  },
};
